package com.example;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ExamplePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(FrozenIconPlugin.class);
		RuneLite.main(args);
	}
}

package com.example;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("frozenIconPlugin")
public interface FrozenIconConfig extends Config
{
    @Range(max = 100)
    @ConfigItem(
            keyName = "size",
            name = "Size",
            description = "Adjust the size of the icon."
    )
    default int size()
    {
        return 3;
    }

    @ConfigItem(
            keyName = "freezeTimer",
            name = "Freeze timer",
            description = "Show freeze timer next to icon."
    )
    default TimeUnit freezeTimer()
    {
        return TimeUnit.SECONDS;
    }

    @ConfigItem(
            keyName = "position",
            name = "Icon position",
            description = "Change what side of the HP bar icon appears."
    )
    default IconOrientation iconOrientation()
    {
        return IconOrientation.RIGHT;
    }

    @ConfigItem(
            keyName = "immunity",
            name = "Show re-freeze immunity",
            description = "Display a shield icon when immune from re-freeze."
    )
    default boolean showImmunity()
    {
        return false;
    }

    @ConfigItem(
            keyName = "teleBlock",
            name = "Show Tele Block",
            description = "Display a tele block icon when you are tele blocked."
    )
    default boolean showTeleBlock()
    {
        return false;
    }
}

package com.example;

public enum IconOrientation
{
    LEFT,
    RIGHT
}

package com.example;

import java.time.Instant;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicChanged;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Frozen Icon"
)
public class FrozenIconPlugin extends Plugin
{
    protected final String FROZEN_MSG = "<col=ef1020>You have been frozen!</col>";
    protected final int BIND_ID = 319;
    protected final int BIND_TICKS = 8;
    protected final int SNARE_ID = 320;
    protected final int SNARE_TICKS = 17;
    protected final int ENTANGLE_ID = 321;
    protected final int ENTANGLE_TICKS = 25;
    protected final int ICE_BARRAGE_ID = 328;
    protected final int ICE_BARRAGE_TICKS = 33;
    protected final int ICE_BLITZ_ID = 326;
    protected final int ICE_BLITZ_TICKS = 17;
    protected final int ICE_BURST_ID = 327;
    protected final int ICE_BURST_TICKS = 25;
    protected final int ICE_RUSH_ID = 325;
    protected final int ICE_RUSH_TICKS = 8;
    protected final int TELE_BLOCK_TICKS = 500;
    protected final int TELE_BLOCK_ID = 352;
    protected final int SHIELD_IMMUNITY = 760;

    @Inject
	private Client client;

    @Inject
    private FrozenIconConfig config;

	@Inject
	private FrozenIconOverlay frozenIconOverlay;

	@Inject
	private OverlayManager overlayManager;

	@Getter
	private int stopFreezeTick;

	@Getter
	private boolean isFrozen;

	@Getter
	private int spriteId;

	@Getter
	private int freezeTime;

    @Getter
    private Instant freezeTimeSecs;

    @Getter
    private Instant endFreezeTimeSecs;

    @Getter
    private WorldPoint frozenLocation;

    @Getter
    private boolean widthOffset;

    @Getter
    private boolean lengthOffset;

    @Getter
    private boolean isTb;

    @Getter
    private int stopTbTick;

    @Getter
    private int stopImmunityTick;

    @Getter
    private boolean isShield;

    private int freezeTick;

    private boolean freezePending;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(frozenIconOverlay);
		log.info("Frozen icon plug in started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(frozenIconOverlay);
		log.info("Frozen icon plug in stopped!");
	}

	@Provides
	FrozenIconConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FrozenIconConfig.class);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.SPAM && event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = event.getMessage();
		if (message.contains(FROZEN_MSG))
		{
			freezePending = true;
		}
	}

    @Subscribe
    public void onGameTick(GameTick event)
    {
        Player player = client.getLocalPlayer();
        WorldPoint currentWorldPoint = player.getWorldLocation();

        if (freezePending)
        {
            findIceSpell();
            frozenLocation = player.getWorldLocation();
            freezePending = false;
        }

        int currTick = client.getTickCount();

        if (isTb && (currTick >= stopTbTick || (player.getInteracting() != null && player.getInteracting().isDead())))
        {
            resetTb();
        }

        if (isShield && currTick >= stopImmunityTick) resetImmunity();

        if (isFrozen && (currTick >= stopFreezeTick || !currentWorldPoint.equals(frozenLocation)))
        {
            resetFreeze();
            if (config.showImmunity())
            {
                isShield = true;
                stopImmunityTick = 5 + client.getTickCount();
            }
        }
        freezeTime = freezeTime > 0 ? freezeTime-1:freezeTime;
    }

    @Subscribe
    public void onActorDeath(ActorDeath actorDeath) {
        Player player = client.getLocalPlayer();
        if (actorDeath.getActor() == player)
        {
            resetFreeze();
            resetTb();
            resetImmunity();
        }
    }

    @Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		Player player = client.getLocalPlayer();
        Actor actor = event.getActor();
		if (actor != player)
		{
			return;
		}

        int gfxId = actor.getGraphic();
        switch (gfxId)
		{
            case SpotanimID.BIND_IMPACT: freezeTick = BIND_TICKS; spriteId = BIND_ID; break;
            case SpotanimID.SNARE_IMPACT: freezeTick = SNARE_TICKS; spriteId = SNARE_ID; break;
            case SpotanimID.ENTANGLE_IMPACT: freezeTick = ENTANGLE_TICKS; spriteId = ENTANGLE_ID; break;
            case SpotanimID.TELE_BLOCK_IMPACT:
                if (isTb || !config.showTeleBlock()) return;
                stopTbTick = (player.getOverheadIcon() != HeadIcon.MAGIC ?
                            TELE_BLOCK_TICKS:(TELE_BLOCK_TICKS/2)) + client.getTickCount();
                isTb = true;
                return;
			default: return;
		}

		isFrozen = true;
        freezeTimeSecs = Instant.now();
        endFreezeTimeSecs = Instant.now().plusSeconds((long)(freezeTick * .6));
		freezeTime = freezeTick;
        stopFreezeTick = freezeTick + client.getTickCount();
        frozenLocation = player.getWorldLocation();
    }

	private void findIceSpell()
	{
		Player player = client.getLocalPlayer();

        int gfxId = player.getGraphic();
        switch (gfxId)
        {
            case SpotanimID.ICE_BARRAGE_IMPACT: freezeTick = ICE_BARRAGE_TICKS; spriteId = ICE_BARRAGE_ID; break;
            case SpotanimID.ICE_BURST_IMPACT: freezeTick = ICE_BURST_TICKS; spriteId = ICE_BURST_ID; lengthOffset = true; break;
            case SpotanimID.ICE_BLITZ_IMPACT: freezeTick = ICE_BLITZ_TICKS; spriteId = ICE_BLITZ_ID; break;
            case SpotanimID.ICE_RUSH_IMPACT: freezeTick = ICE_RUSH_TICKS;  spriteId = ICE_RUSH_ID; widthOffset = true; break;
            default: return;
        }

		isFrozen = true;
        freezeTimeSecs = Instant.now();
        endFreezeTimeSecs = Instant.now().plusSeconds((long)(freezeTick * .6));
		freezeTime = freezeTick;
        stopFreezeTick = freezeTick + client.getTickCount();
	}

    private void resetFreeze()
    {
        spriteId = 0;
        freezeTick = 0;
        stopFreezeTick = 0;
        freezeTime = 0;
        widthOffset = false;
        lengthOffset = false;
        isFrozen = false;
    }

    private void resetTb()
    {
        isTb = false;
        stopTbTick = 0;
    }

    private void resetImmunity()
    {
        isShield = false;
        stopImmunityTick = 0;
    }
}

package com.example;

public enum TimeUnit
{
    SECONDS,
    TICKS,
    NONE
}

package com.example;

import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import javax.inject.Inject;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

public class FrozenIconOverlay extends Overlay
{
    private final Client client;
    private final SpriteManager spriteManager;
    private final FrozenIconConfig config;
    private final FrozenIconPlugin plugin;

    @Inject
    FrozenIconOverlay(Client client, SpriteManager spriteManager, FrozenIconConfig config, FrozenIconPlugin plugin)
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        this.client = client;
        this.spriteManager = spriteManager;
        this.config = config;
        this.plugin = plugin;
    }

    @Override
    public Dimension render(Graphics2D graphics2D)
    {
        Player player = client.getLocalPlayer();
        if (player == null || player.getPlayerComposition() == null)
        {
            return null;
        }

        if (plugin.isFrozen() || (plugin.isTb() && config.showTeleBlock())
            || (plugin.isShield() && config.showImmunity()))
        {
            int adjustIcon = 5;
            List<Integer> icons = new ArrayList<>();
            int frozenIcon = plugin.isFrozen() ? plugin.getSpriteId():
                    (plugin.isShield() ? plugin.SHIELD_IMMUNITY:0);

            if (plugin.isTb()) icons.add(plugin.TELE_BLOCK_ID);

            if (frozenIcon != 0) icons.add(0,frozenIcon);

            for (int icon : icons)
            {
                BufferedImage iconImg = spriteManager.getSprite(icon, 0);
                int shieldAdj = icon == plugin.SHIELD_IMMUNITY ? 5:0;

                if (icon != 0 && iconImg != null)
                {
                    int modelHeight = player.getLogicalHeight();
                    Point canvasPoint = Perspective.getCanvasImageLocation(
                            client,
                            player.getLocalLocation(),
                            iconImg,
                            modelHeight);

                    int yOffset = plugin.isLengthOffset() ? 8:16;
                    int xOffset = plugin.isWidthOffset() ? 8:16;
                    int selectedSize = config.size();

                    if (canvasPoint != null)
                    {
                        int iconOffset = config.iconOrientation() == IconOrientation.RIGHT ? 25:-25;

                        graphics2D.drawImage(
                                iconImg,
                                canvasPoint.getX() + iconOffset + shieldAdj + (icon == plugin.ICE_BURST_ID ? 6:0),
                                canvasPoint.getY() - adjustIcon + shieldAdj,
                                selectedSize + yOffset - shieldAdj,
                                selectedSize + xOffset - shieldAdj,
                                null
                        );

                        if (!config.freezeTimer().equals(TimeUnit.NONE) && icon != plugin.SHIELD_IMMUNITY
                            && icon != plugin.TELE_BLOCK_ID)
                        {
                            if (plugin.getFreezeTime() <= 5)
                            {
                                graphics2D.setColor(Color.RED);
                            }

                            graphics2D.setFont(graphics2D.getFont().deriveFont(
                                    graphics2D.getFont().getStyle(),
                                    graphics2D.getFont().getSize() + selectedSize
                            ));

                            int timerOffset = config.iconOrientation() == IconOrientation.RIGHT ? 45:-45;
                            int timeToShow = config.freezeTimer().equals(TimeUnit.SECONDS) ?
                                    (int) Duration.between(Instant.now(), plugin.getEndFreezeTimeSecs()).toSeconds()
                                    :plugin.getFreezeTime();

                            timeToShow = Math.max(0, timeToShow);
                            graphics2D.drawString(
                                    String.valueOf(timeToShow),
                                    canvasPoint.getX() + selectedSize + timerOffset,
                                    canvasPoint.getY() + selectedSize + 11 - adjustIcon
                            );
                        }
                    }
                    adjustIcon += selectedSize + yOffset;
                }
            }
        }
        return null;
    }
}
